//! The extension's real `import.archive` payload (generated by
//! `apps/extension/scripts/bridge-fixtures.ts` from a seeded `IndexedDB`) imports into the app.

use decay_core::{ItemState, Mode, Reason};
use decay_store::{DbKey, ImportReport, Platform, Store, StorePaths};

#[test]
fn the_extension_archive_imports() {
    let archive: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/import_archive.json")).expect("fixture parses");
    let dir = tempfile::tempdir().unwrap();
    let now = 1_793_750_400_000;
    let (mut store, _) =
        Store::open(StorePaths::in_dir(dir.path()), DbKey::from_bytes([1; 32]), now).unwrap();
    let report = store.import_archive(&archive, Platform::MacOs, now).unwrap();
    assert_eq!(
        report,
        ImportReport {
            items_imported: 3,
            items_existing: 0,
            items_updated: 0,
            items_live: 0, // the extension only sends archived / restored records
            items_invalid: 0,
            items_expired: 0,
            items_purged: 0,
            rules_imported: 3,
            rules_existing: 1, // the default rule
            rules_invalid: 0,
            rules_turned_off: 0,
            settings_imported: 11, // a fresh app: every setting, and the earlier shadow start
        }
    );
    assert_eq!(store.mode().unwrap(), Mode::Automatic);
    assert_eq!(store.setting::<u32>("retention_days").unwrap(), Some(30));
    assert_eq!(store.setting::<u32>("idle_cutoff_s").unwrap(), Some(600));
    assert!(store.setting::<i64>("shadow_started_at").unwrap().unwrap() < now - 29 * 86_400_000);

    let items = archive["items"].as_array().unwrap();
    let edge = items.iter().find(|i| i["appId"] == "com.microsoft.Edge").unwrap();
    let edge = store.item(edge["id"].as_str().unwrap()).unwrap().unwrap();
    assert_eq!(edge.app_id, "com.microsoft.edgemac");
    assert!(matches!(edge.archive_reason, Some(Reason::CustomRule { .. })));
    let restored = items.iter().find(|i| i["state"] == "restored").unwrap();
    let restored = store.item(restored["id"].as_str().unwrap()).unwrap().unwrap();
    assert_eq!(restored.state, ItemState::Restored);
    assert!(restored.restored_from_id.is_some());

    // Importing again changes nothing.
    let again = store.import_archive(&archive, Platform::MacOs, now).unwrap();
    assert_eq!((again.items_imported, again.rules_imported), (0, 0));
}
